insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'high', 'Try a raw honey mask', 'Many people in the beauty community apply a thin layer of raw honey for 20–30 minutes before rinsing. Some say it helped calm painful breakouts over a few weeks of consistent use.', 1);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'high', 'Gentle cold compress', 'Wrapping an ice cube in a clean cloth and pressing it gently on swollen spots for a few minutes may help reduce redness. Creators often mention this before filming.', 2);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'high', 'Diluted apple cider vinegar toner', 'Mix one part apple cider vinegar with three parts water, dab with a cotton pad after cleansing, and see how your skin responds. Start once a day.', 3);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'high', 'Simplify your routine', 'When breakouts flare up, many people strip back to a gentle cleanser and lightweight moisturizer for two to three weeks to reduce irritation.', 4);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'medium', 'Spot treat with tea tree oil', 'Dilute a drop of tea tree oil and dab on individual spots with a cotton swab. Many creators share this as an overnight trick that may reduce redness by morning.', 1);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'medium', 'Green tea toner', 'Brew green tea, cool it, and use it as a toner. Some users say regular use made mild breakouts look less noticeable over time.', 2);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'medium', 'Wash pillowcases often', 'Switching to a clean cotton pillowcase every two to three days is a simple habit many creators credit for fewer cheek and jawline breakouts.', 3);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'medium', 'Clay mask once a week', 'A weekly clay or charcoal mask may help with congestion. People often say skin looks cleaner after regular use.', 4);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'low', 'Lukewarm water cleanse', 'Many people say switching to lukewarm water and a gentle cleanser morning and night helped occasional breakouts over time.', 1);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'low', 'Rice water rinse', 'Soak rice in water for 15–20 minutes, strain, and rinse your face. Asian beauty creators often share this for a clearer-looking complexion.', 2);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'low', 'Hands off your face', 'Being mindful about not touching your face through the day may reduce how often new spots appear, according to many users.', 3);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('acne', 'low', 'Aloe vera gel moisturizer', 'Pure aloe vera gel is a fan favourite for lightweight hydration that some say helps keep occasional breakouts calmer.', 4);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'high', 'Turmeric and honey mask', 'Mix a pinch of turmeric with honey, apply to dark areas for about 15 minutes, and rinse. Many creators rave about brighter-looking skin over consistent weeks.', 1);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'high', 'Daily sunscreen', 'Many people say daily SPF was the biggest change for fading dark marks and preventing new ones — even on cloudy days.', 2);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'high', 'Potato slice rub', 'Some creators gently rub raw potato slices on dark spots daily. It has a following in natural beauty communities.', 3);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'high', 'Diluted lemon rinse', 'A few drops of lemon in water on a cotton pad may help some people brighten dark areas — always patch test first.', 4);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'medium', 'Cucumber under eyes', 'Cool cucumber slices for 10–15 minutes are a classic trick many users say freshened under-eye darkness over time.', 1);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'medium', 'Aloe on dark marks', 'Pure aloe vera on post-blemish marks is gentle for daily use; many say marks faded gradually.', 2);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'medium', 'Rice water brightening', 'Rice water as a toner after cleansing is popular for a more even-looking tone with regular use.', 3);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'medium', 'Cold spoons for circles', 'Chilled spoons under the eyes in the morning may help dark circles look less pronounced, creators often share.', 4);
insert into beauty_tip_entries (category_id, severity, title, body, sort_order) values ('hyperpigmentation', 'low', 'Consistent cleansing', 'Sticking to morning and evening cleanse helped many people with faint marks look more even over time.', 1);
